<?php require_once 'includes/config.php'; require_once 'includes/phase1.php';
$rollid=trim($_POST['rollid']??''); $classid=(int)($_POST['class']??0); $year=trim($_POST['academic_year']??''); $term=trim($_POST['term']??'Final'); $exam=trim($_POST['exam_type']??'');
if (!$rollid || !$classid || !$year || !$exam) { header('Location: find-result.php'); exit; }
$studentQ=$dbh->prepare('SELECT s.StudentId,s.StudentName,s.RollId,c.ClassName,c.Section FROM tblstudents s JOIN tblclasses c ON c.id=s.ClassId WHERE s.RollId=:roll AND s.ClassId=:class LIMIT 1'); $studentQ->execute([':roll'=>$rollid,':class'=>$classid]); $student=$studentQ->fetch();
$rows=[]; $total=0; $outof=0;
if($student){ $q=$dbh->prepare("SELECT sub.SubjectName,r.marks,r.MaxMarks FROM tblresult r JOIN tblsubjects sub ON sub.id=r.SubjectId WHERE r.StudentId=:sid AND r.ClassId=:cid AND r.AcademicYear=:year AND r.Term=:term AND r.ExamType=:exam AND r.Published=1 AND r.approval_state='approved' AND r.result_status='approved' ORDER BY sub.SubjectName"); $q->execute([':sid'=>$student['StudentId'],':cid'=>$classid,':year'=>$year,':term'=>$term,':exam'=>$exam]); $rows=$q->fetchAll(); foreach($rows as $r){$total+=(int)$r['marks'];$outof+=(int)$r['MaxMarks'];} }
$percentage=$outof?($total/$outof)*100:0; [$grade,$remark]=grade_for($percentage);
?><!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Result | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"><style>@media print{.no-print{display:none!important}.panel{border:0}}</style></head><body><div class="container" id="exampl" style="max-width:900px;margin:30px auto"><div class="panel"><div class="panel-heading text-center"><h2>Student Result</h2><p><?php echo e(APP_NAME); ?></p></div><div class="panel-body"><?php if(!$student): ?><div class="alert alert-danger">Invalid roll number or class.</div><?php elseif(!$rows): ?><div class="alert alert-warning">The result has not been published for this academic year/examination.</div><?php else: ?><div class="row"><div class="col-sm-6"><p><b>Student:</b> <?php echo e($student['StudentName']); ?></p><p><b>Roll ID:</b> <?php echo e($student['RollId']); ?></p><p><b>Class:</b> <?php echo e($student['ClassName'].' ('.$student['Section'].')'); ?></p></div><div class="col-sm-6"><p><b>Academic Year:</b> <?php echo e($year); ?></p><p><b>Examination:</b> <?php echo e($exam); ?></p></div></div><table class="table table-bordered"><thead><tr><th>#</th><th>Subject</th><th>Marks</th><th>Grade</th></tr></thead><tbody><?php foreach($rows as $i=>$r): $pct=((int)$r['marks']/(int)$r['MaxMarks'])*100; [$g,] = grade_for($pct); ?><tr><td><?php echo $i+1; ?></td><td><?php echo e($r['SubjectName']); ?></td><td><?php echo (int)$r['marks']; ?> / <?php echo (int)$r['MaxMarks']; ?></td><td><?php echo e($g); ?></td></tr><?php endforeach; ?><tr><th colspan="2">Total</th><th colspan="2"><?php echo $total; ?> / <?php echo $outof; ?></th></tr><tr><th colspan="2">Percentage</th><th colspan="2"><?php echo number_format($percentage,2); ?>%</th></tr><tr><th colspan="2">Overall Grade</th><th><?php echo e($grade); ?></th><th><?php echo e($remark); ?></th></tr></tbody></table><?php endif; ?><div class="no-print"><button onclick="window.print()" class="btn btn-primary"><i class="fa fa-print"></i> Print</button> <a class="btn btn-success" href="report-card.php?rollid=<?php echo urlencode($rollid); ?>&class=<?php echo (int)$classid; ?>&academic_year=<?php echo urlencode($year); ?>&term=<?php echo urlencode($term); ?>&exam_type=<?php echo urlencode($exam); ?>">Official Report Card</a> <a href="find-result.php" class="btn btn-default">Search Again</a></div></div></div></div></body></html>
